"""
Slide Studio — builds presentations in Docente's own templates from a simple
description of a deck (the "deck model" the in-app slide editor edits).

Two families of templates, each built from a real deck its users shared, with
every slide, photo, personal detail and piece of leftover text removed so only
the design (slide master, layouts, theme) remains:

  Student  From a student clinical-practice presentation: a navy title slide
           with a two-tone band along the bottom; on every other slide a band
           under the centred title with the slide number in a coloured chip.
           Title slide: institution lines, logo, main and second lines, label.
  Tutor    From a lecture deck: a white title slide with a picture held in
           two corner brackets and a serif course title; content slides with a
           left-aligned serif title over a thin rule and a dark band along the
           bottom carrying the course (footer) and slide number. Title slide:
           course, code, lecture title, lecturer, date, optional picture.

Each family has three colour versions (TEMPLATES). Colours go through theme
colours wherever the design allows, so titles, bullets, tables and charts
match whichever version is chosen.
"""
import base64
import copy
import io
import math
import os
import re

from lxml import etree
from pptx import Presentation
from pptx.chart.data import CategoryChartData
from pptx.dml.color import RGBColor
from pptx.enum.chart import XL_CHART_TYPE, XL_LEGEND_POSITION
from pptx.enum.dml import MSO_THEME_COLOR
from pptx.enum.shapes import MSO_CONNECTOR, MSO_SHAPE, PP_PLACEHOLDER
from pptx.enum.text import MSO_ANCHOR, MSO_AUTO_SIZE, PP_ALIGN
from pptx.opc.constants import RELATIONSHIP_TYPE as RT
from pptx.oxml.ns import qn
from pptx.util import Inches, Pt


class StudioError(Exception):
    """A problem with the deck the person can fix — shown to them as is."""


