# theme: theme-colour overrides. band/panel/frame: colours the tutor design
# draws directly (its bottom band, closing panel and title-slide frame).
TEMPLATES = {
    "student-classic": {"group": "student", "name": "Classic Blue", "theme": None},
    "student-emerald": {"group": "student", "name": "Emerald",
                        "theme": {"dk2": "173A30", "lt2": "D9F0E4", "accent1": "1F7A57", "accent2": "F2B33D"}},
    "student-crimson": {"group": "student", "name": "Crimson",
                        "theme": {"dk2": "3A1321", "lt2": "F6DDE3", "accent1": "A3243F", "accent2": "F2B33D"}},
    "tutor-classic": {"group": "tutor", "name": "Lecture Orange", "theme": None,
                      "band": "262626", "panel": "3A4245", "frame": "FF6D17"},
    "tutor-teal": {"group": "tutor", "name": "Lecture Teal", "theme": {"accent1": "1C9C9C"},
                   "band": "1E2B30", "panel": "22393F", "frame": "18A5A5"},
    "tutor-navy": {"group": "tutor", "name": "Lecture Navy", "theme": {"accent1": "3F5DAB"},
                   "band": "1B2340", "panel": "25305A", "frame": "D9A21B"},
}
ALIASES = {"student": "student-classic", "tutor": "tutor-classic"}

# Where things go on a content slide, per family (inches: left, top, width, height)
GEOMETRY = {
    "student": {"body": (0.89, 1.9, 11.89, 4.8), "right_text_w": 6.2, "right_media": (7.35, 2.0, 5.4, 4.6),
                "below_text_h": 1.75, "below_media": (0.89, 3.75, 11.89, 3.0), "full_media": (0.89, 2.0, 11.89, 4.7)},
    "tutor": {"body": (1.2, 2.3, 11.0, 4.5), "right_text_w": 5.8, "right_media": (7.25, 2.4, 5.1, 4.35),
              "below_text_h": 1.6, "below_media": (1.2, 4.05, 11.0, 2.75), "full_media": (1.2, 2.35, 11.0, 4.45)},
}

MAX_SLIDES = 60
MAX_IMAGE_BYTES = 6 * 1024 * 1024
WHITE = RGBColor(0xFF, 0xFF, 0xFF)
SLIDE_W, SLIDE_H = Inches(13.333), Inches(7.5)


def template_catalog():
    """For the app: [{id, name, group}] in display order."""
    return [{"id": k, "name": v["name"], "group": v["group"]} for k, v in TEMPLATES.items()]


def _resolve(key):
    key = ALIASES.get(key, key)
    if key not in TEMPLATES:
        raise StudioError("Unknown template — please choose one from the list.")
    return key, TEMPLATES[key]


def _open_template(key):
    key, tpl = _resolve(key)
    prs = Presentation(io.BytesIO(base64.b64decode("".join(_BASES[tpl["group"]]))))
    if tpl.get("theme"):
        theme_part = prs.slide_masters[0].part.part_related_by(RT.THEME)
        xml = theme_part.blob.decode("utf-8")
        for slot, hex_ in tpl["theme"].items():
            xml = re.sub(r'(<a:%s>\s*<a:srgbClr val=")[0-9A-Fa-f]{6}(")' % slot, r"\g<1>%s\g<2>" % hex_, xml)
        theme_part._blob = xml.encode("utf-8")
    if tpl["group"] == "tutor" and tpl.get("band") and tpl["band"] != "262626":
        # The lecture design draws its dark band (and the closing slide's
        # panel) in a fixed colour on the master and layouts, not a theme
        # colour — so the colour versions recolour those shapes directly.
        master = prs.slide_masters[0]
        for el in [master._element] + [lay._element for lay in master.slide_layouts]:
            for clr in el.iter(qn("a:srgbClr")):
                if clr.get("val", "").upper() == "262626":
                    clr.set("val", tpl["band"])
    return prs, key, tpl


def _layout(prs, name):
    for lay in prs.slide_masters[0].slide_layouts:
        if lay.name == name:
            return lay
    raise StudioError(f"The template is missing its '{name}' layout.")


def _remove(shape):
    shape._element.getparent().remove(shape._element)


def _to_back(shape):
    """Just above the slide's group properties — behind every other shape."""
    tree = shape._element.getparent()
    tree.remove(shape._element)
    tree.insert(2, shape._element)


def _image_bytes(value):
    """Picture data from a data: URL or bare base64, checked to be a real,
    reasonably sized image so a bad upload fails clearly, not mid-build."""
    if not value:
        return None
    if isinstance(value, str) and value.startswith("data:"):
        value = value.split(",", 1)[-1]
    try:
        data = base64.b64decode(value, validate=False)
    except Exception:
        raise StudioError("One of the pictures couldn't be read.")
    if len(data) > MAX_IMAGE_BYTES:
        raise StudioError("One of the pictures is larger than 6 MB — please use a smaller one.")
    try:
        from PIL import Image
        with Image.open(io.BytesIO(data)) as im:
            im.verify()
    except Exception:
        raise StudioError("One of the pictures isn't an image this can use (JPG or PNG work best).")
    return data


def _image_size(data):
    from PIL import Image
    with Image.open(io.BytesIO(data)) as im:
        return im.size


def _fit_picture(slide, data, left, top, width, height):
    """Whole picture, as large as fits, centred (logos, charts, diagrams)."""
    iw, ih = _image_size(data)
    scale = min(width / iw, height / ih)
    w, h = int(iw * scale), int(ih * scale)
    return slide.shapes.add_picture(io.BytesIO(data), left + (width - w) // 2, top + (height - h) // 2, w, h)


def _fill_picture(slide, data, left, top, width, height):
    """Picture filling the box, trimmed evenly at the edges (a photo inside
    the tutor title slide's frame)."""
    iw, ih = _image_size(data)
    pic = slide.shapes.add_picture(io.BytesIO(data), left, top, width, height)
    box, img = width / height, iw / ih
    if img > box:
        trim = (1 - box / img) / 2
        pic.crop_left = pic.crop_right = trim
    elif img < box:
        trim = (1 - img / box) / 2
        pic.crop_top = pic.crop_bottom = trim
    return pic


def _next_shape_id(slide):
    ids = [int(x) for x in slide.shapes._spTree.xpath(".//p:cNvPr/@id") if str(x).isdigit()]
    return max(ids + [1]) + 1


def _clone_layout_placeholder(slide, layout, ph_type):
    src = next((ph for ph in layout.placeholders if ph.placeholder_format.type == ph_type), None)
    if src is None:
        return None
    el = copy.deepcopy(src._element)
    el.find(".//" + qn("p:cNvPr")).set("id", str(_next_shape_id(slide)))
    tx = el.find(qn("p:txBody"))
    for p in tx.findall(qn("a:p")):
        tx.remove(p)
    slide.shapes._spTree.append(el)
    return el, tx


def _run_props(parent, size_pt, bold, scheme_colour, font=None):
    rpr = etree.SubElement(parent, qn("a:rPr"), lang="en-US", sz=str(int(size_pt * 100)), b="1" if bold else "0")
    fill = etree.SubElement(rpr, qn("a:solidFill"))
    etree.SubElement(fill, qn("a:schemeClr"), val=scheme_colour)
    if font:
        etree.SubElement(rpr, qn("a:latin"), typeface=font)
    return rpr


def _add_slide_number(slide, layout, number, group):
    """A live slide-number field in the template's own slot, made prominent:
    Student — bold, dark, in the band's coloured chip (the original's white
    number on cyan was hard to read, about 1.8:1; this is about 9:1).
    Tutor — bold and white, larger, on the dark band's right end."""
    made = _clone_layout_placeholder(slide, layout, PP_PLACEHOLDER.SLIDE_NUMBER)
    if made is None:
        return
    el, tx = made
    body_pr = tx.find(qn("a:bodyPr"))
    body_pr.set("anchor", "ctr")
    if group == "student":
        for k in ("lIns", "tIns", "rIns", "bIns"):
            body_pr.set(k, "0")
    p = etree.SubElement(tx, qn("a:p"))
    etree.SubElement(p, qn("a:pPr"), algn="ctr" if group == "student" else "r")
    fld = etree.SubElement(p, qn("a:fld"), id="{B6F15528-21DE-4FAA-801E-634DDDAF4B2B}", type="slidenum")
    if group == "student":
        _run_props(fld, 14, True, "tx2", "Arial Black")
    else:
        _run_props(fld, 16, True, "bg1")
    etree.SubElement(fld, qn("a:t")).text = str(number)


def _add_footer(slide, layout, text):
    """Tutor slides: the course on the dark band, so every slide says which
    course and lecture it belongs to."""
    text = (text or "").strip()
    if not text:
        return
    made = _clone_layout_placeholder(slide, layout, PP_PLACEHOLDER.FOOTER)
    if made is None:
        return
    el, tx = made
    tx.find(qn("a:bodyPr")).set("anchor", "ctr")
    p = etree.SubElement(tx, qn("a:p"))
    r = etree.SubElement(p, qn("a:r"))
    _run_props(r, 12, False, "bg1")
    etree.SubElement(r, qn("a:t")).text = text[:90]


def _number_paragraph(paragraph):
    """1. 2. 3. numbering in the template's accent colour, as the student
    deck numbers its outline and lists."""
    ppr = paragraph._p.get_or_add_pPr()
    for tag in ("a:buNone", "a:buAutoNum", "a:buChar", "a:buBlip", "a:buClr", "a:buClrTx", "a:buFont", "a:buFontTx"):
        for el in ppr.findall(qn(tag)):
            ppr.remove(el)
    clr = etree.Element(qn("a:buClr"))
    etree.SubElement(clr, qn("a:schemeClr"), val="accent2")
    auto = etree.Element(qn("a:buAutoNum"), type="arabicPeriod")
    anchor = ppr.find(qn("a:tabLst")) if ppr.find(qn("a:tabLst")) is not None else ppr.find(qn("a:defRPr"))
    if anchor is not None:
        anchor.addprevious(clr)
        anchor.addprevious(auto)
    else:
        ppr.append(clr)
        ppr.append(auto)


def _body_size(bullets, width_in, height_in, top=30):
    """The largest size (top pt down to 16pt) at which every bullet, wrapped,
    fits its box. Preview engines shrink text unpredictably, so the size is
    chosen here, measured against the wider substitute font a computer
    without the template's font falls back to — so nothing spills out
    anywhere the deck is opened."""
    for size in [s for s in (30, 28, 26, 24, 22, 20, 18, 16) if s <= top]:
        per_line = max(8, int((width_in - 0.3) * 72 / (size * 0.58)))
        lines = 0
        for b in bullets:
            lines += max(1, math.ceil(len(b["text"]) / max(8, per_line - 3 - 3 * b["level"])))
        if lines * size * 1.2 + len(bullets) * size * 0.45 <= height_in * 72:
            return size
    return 16


def _clean_bullets(raw):
    out = []
    for b in raw or []:
        if isinstance(b, str):
            b = {"text": b, "level": 0}
        if not isinstance(b, dict):
            continue
        text = str(b.get("text", "")).strip()
        if text:
            out.append({"text": text[:600], "level": max(0, min(int(b.get("level", 0) or 0), 3))})
    return out[:40]


def _write_bullets(placeholder, bullets, box_in, numbered):
    """Fills a body placeholder with bullets sized to fit the box."""
    tf = placeholder.text_frame
    tf.word_wrap = True
    # The templates' body boxes shrink text to fit, and preview engines shrank
    # even lists that fit easily (28pt came out at about 17pt), so shrinking
    # is off and the size chosen by _body_size keeps text inside the box.
    tf.auto_size = MSO_AUTO_SIZE.NONE
    tf.text = ""
    size = _body_size(bullets, box_in[2], box_in[3])
    for i, b in enumerate(bullets):
        p = tf.paragraphs[0] if i == 0 else tf.add_paragraph()
        p.level = b["level"]
        if numbered and b["level"] == 0:
            _number_paragraph(p)
        r = p.add_run()
        r.text = b["text"]
        r.font.size = Pt(size if b["level"] == 0 else max(size - 4, 14))


def _add_table(slide, spec, left, top, width, height):
    rows = [[str(c if c is not None else "")[:200] for c in r] for r in (spec.get("rows") or []) if isinstance(r, list)]
    rows = [r for r in rows if any(c.strip() for c in r)][:20]
    if not rows:
        return
    n_cols = min(max(len(r) for r in rows), 10)
    rows = [(r + [""] * n_cols)[:n_cols] for r in rows]
    h = min(height, Inches(0.46) * len(rows))
    table = slide.shapes.add_table(len(rows), n_cols, left, top, width, h).table
    size = Pt(16 if len(rows) <= 6 and n_cols <= 4 else 13 if len(rows) <= 10 else 11)
    for r_i, row in enumerate(rows):
        for c_i in range(n_cols):
            cell = table.cell(r_i, c_i)
            cell.text = row[c_i]
            cell.fill.solid()
            cell.fill.fore_color.theme_color = MSO_THEME_COLOR.ACCENT_1
            if r_i:
                cell.fill.fore_color.brightness = 0.9 if r_i % 2 else 0.8
            for p in cell.text_frame.paragraphs:
                for run in p.runs:
                    run.font.size = size
                    run.font.bold = r_i == 0
                    if r_i == 0:
                        run.font.color.rgb = WHITE
                    else:
                        run.font.color.theme_color = MSO_THEME_COLOR.TEXT_1


_CHART_TYPES = {"column": XL_CHART_TYPE.COLUMN_CLUSTERED, "bar": XL_CHART_TYPE.BAR_CLUSTERED,
                "line": XL_CHART_TYPE.LINE_MARKERS, "pie": XL_CHART_TYPE.PIE}


def _add_chart(slide, spec, left, top, width, height):
    cats = [str(c)[:40] for c in (spec.get("categories") or [])][:24]
    series = []
    for s in (spec.get("series") or [])[:6]:
        if not isinstance(s, dict):
            continue
        vals = []
        for v in (s.get("values") or [])[:len(cats)]:
            try:
                vals.append(float(v))
            except (TypeError, ValueError):
                vals.append(0.0)
        if vals:
            series.append((str(s.get("name") or "Series")[:40], vals + [0.0] * (len(cats) - len(vals))))
    if not cats or not series:
        return
    kind = spec.get("chart_type") if spec.get("chart_type") in _CHART_TYPES else "column"
    if kind == "pie":
        series = series[:1]
    data = CategoryChartData()
    data.categories = cats
    for name, vals in series:
        data.add_series(name, vals)
    chart = slide.shapes.add_chart(_CHART_TYPES[kind], left, top, width, height, data).chart
    chart.font.size = Pt(14)
    chart.has_legend = kind == "pie" or len(series) > 1
    if chart.has_legend:
        chart.legend.position = XL_LEGEND_POSITION.BOTTOM
        chart.legend.include_in_layout = False
    if spec.get("title"):
        chart.has_title = True
        chart.chart_title.text_frame.text = str(spec["title"])[:80]
        chart.chart_title.text_frame.paragraphs[0].runs[0].font.size = Pt(16)
    if kind == "pie":
        plot = chart.plots[0]
        plot.has_data_labels = True
        plot.data_labels.number_format = "0%"
        plot.data_labels.show_percentage = True
        plot.data_labels.show_value = False


def _add_media(slide, media, box):
    mtype = media.get("type")
    if mtype == "image":
        data = _image_bytes(media.get("data"))
        if data:
            _fit_picture(slide, data, *box)
    elif mtype == "table":
        _add_table(slide, media, *box)
    elif mtype == "chart":
        _add_chart(slide, media, *box)


def _student_title_slide(prs, deck):
    """Mirrors the student deck: institution, department and programme in
    white capitals across the top of the navy slide; logo centred; the main
    line and a second line below; an optional small label top-right."""
    ts = deck.get("title_slide") or {}
    s = prs.slides.add_slide(_layout(prs, "Title Slide"))
    for ph in list(s.placeholders):
        if ph.placeholder_format.type not in (PP_PLACEHOLDER.TITLE, PP_PLACEHOLDER.CENTER_TITLE):
            _remove(ph)
    lines = [str(l).strip()[:120] for l in (ts.get("lines") or []) if str(l).strip()][:4] or ["Your institution"]
    t = s.shapes.title
    t.left, t.top, t.width, t.height = 0, Inches(0.35), SLIDE_W, Inches(2.15)
    tf = t.text_frame
    tf.word_wrap = True
    tf.vertical_anchor = MSO_ANCHOR.MIDDLE
    tf.text = ""
    for i, line in enumerate(lines):
        p = tf.paragraphs[0] if i == 0 else tf.add_paragraph()
        p.alignment = PP_ALIGN.CENTER
        r = p.add_run()
        r.text = line.upper()
        r.font.name = "Arial Black"
        r.font.bold = True
        r.font.size = Pt(22 if len(lines) <= 3 else 18)
        r.font.color.rgb = WHITE
    logo = _image_bytes(deck.get("logo"))
    if logo:
        _fit_picture(s, logo, SLIDE_W // 2 - Inches(0.65), Inches(2.62), Inches(1.3), Inches(1.3))
    y = Inches(4.05) if logo else Inches(3.1)
    for key, size, bold in (("main", 26, True), ("sub", 20, False)):
        text = str(ts.get(key) or "").strip()[:200]
        if not text:
            continue
        box = s.shapes.add_textbox(Inches(0.79), y, Inches(11.75), Inches(1.0))
        box.text_frame.word_wrap = True
        p = box.text_frame.paragraphs[0]
        p.alignment = PP_ALIGN.CENTER
        r = p.add_run()
        r.text = text
        r.font.size = Pt(size)
        r.font.bold = bold
        r.font.color.rgb = WHITE
        y += Inches(1.1)
    tag = str(ts.get("tag") or "").strip()[:40]
    if tag:
        box = s.shapes.add_textbox(Inches(10.4), Inches(0.08), Inches(2.8), Inches(0.36))
        p = box.text_frame.paragraphs[0]
        p.alignment = PP_ALIGN.RIGHT
        r = p.add_run()
        r.text = tag
        r.font.size = Pt(12)
        r.font.color.rgb = WHITE


def _tutor_title_slide(prs, deck, tpl):
    """Mirrors the lecture deck: a white slide; on the left a picture held in
    two corner brackets (redrawn as shapes — the original's frame was a
    picture, and its photos weren't carried over); on the right the course
    title with its code, a thin rule, the lecture title in small capitals,
    and the lecturer and date."""
    ts = deck.get("title_slide") or {}
    s = prs.slides.add_slide(_layout(prs, "Title Slide"))
    keep = (PP_PLACEHOLDER.TITLE, PP_PLACEHOLDER.CENTER_TITLE, PP_PLACEHOLDER.SUBTITLE)
    for ph in list(s.placeholders):
        if ph.placeholder_format.type not in keep:
            _remove(ph)
    cover = s.shapes.add_shape(MSO_SHAPE.RECTANGLE, 0, 0, SLIDE_W, SLIDE_H)
    cover.fill.solid()
    cover.fill.fore_color.rgb = WHITE
    cover.line.fill.background()
    cover.shadow.inherit = False
    _to_back(cover)
    frame = RGBColor.from_string(tpl.get("frame") or "FF6D17")
    for x, y, w, h in ((0.08, 0.45, 2.97, 0.1), (0.08, 0.45, 0.1, 5.42), (1.52, 6.70, 2.95, 0.1), (4.37, 1.38, 0.1, 5.42)):
        bar = s.shapes.add_shape(MSO_SHAPE.RECTANGLE, Inches(x), Inches(y), Inches(w), Inches(h))
        bar.fill.solid()
        bar.fill.fore_color.rgb = frame
        bar.line.fill.background()
        bar.shadow.inherit = False
    picture = _image_bytes(ts.get("picture"))
    logo = _image_bytes(deck.get("logo"))
    if picture:
        # Fitted whole, never cropped: a landscape photo in this portrait frame
        # would otherwise lose its sides.
        _fit_picture(s, picture, Inches(0.47), Inches(1.3), Inches(3.53), Inches(4.33))
    elif logo:
        _fit_picture(s, logo, Inches(0.85), Inches(2.3), Inches(2.8), Inches(2.4))
    course = str(ts.get("course") or "").strip()[:80] or "Course title"
    code = str(ts.get("code") or "").strip()[:30]
    t = s.shapes.title
    t.left, t.top, t.width, t.height = Inches(4.55), Inches(0.7), Inches(8.07), Inches(4.03)
    tf = t.text_frame
    tf.word_wrap = True
    tf.vertical_anchor = MSO_ANCHOR.BOTTOM
    tf.text = ""
    size = Pt(54 if len(course) <= 16 else 44 if len(course) <= 26 else 36)
    for i, text in enumerate([course] + ([f"({code})"] if code else [])):
        p = tf.paragraphs[0] if i == 0 else tf.add_paragraph()
        p.alignment = PP_ALIGN.LEFT
        r = p.add_run()
        r.text = text
        r.font.size = size
    rule = s.shapes.add_connector(MSO_CONNECTOR.STRAIGHT, Inches(5.94), Inches(4.92), Inches(12.1), Inches(4.92))
    rule.line.width = Pt(0.75)
    rule.line.color.theme_color = MSO_THEME_COLOR.TEXT_1
    sub = next((ph for ph in s.placeholders if ph.placeholder_format.type == PP_PLACEHOLDER.SUBTITLE), None)
    subtitle = str(ts.get("subtitle") or "").strip()[:120]
    if sub is not None:
        if subtitle:
            sub.left, sub.top, sub.width, sub.height = Inches(4.69), Inches(5.11), Inches(7.95), Inches(0.8)
            sub.text_frame.text = subtitle
            sub.text_frame.paragraphs[0].alignment = PP_ALIGN.LEFT
        else:
            _remove(sub)
    meta = "  ·  ".join(x for x in (str(ts.get("lecturer") or "").strip()[:80], str(ts.get("date") or "").strip()[:40]) if x)
    if meta:
        box = s.shapes.add_textbox(Inches(4.69), Inches(6.0), Inches(7.95), Inches(0.5))
        r = box.text_frame.paragraphs[0].add_run()
        r.text = meta
        r.font.size = Pt(16)
        r.font.color.theme_color = MSO_THEME_COLOR.TEXT_1
        r.font.color.brightness = 0.25


def _set_title(slide, text, group):
    t = slide.shapes.title
    tf = t.text_frame
    tf.text = ""
    p = tf.paragraphs[0]
    r = p.add_run()
    r.text = text or " "
    n = len(text or "")
    if group == "student":
        p.alignment = PP_ALIGN.CENTER
        r.font.name = "Arial Black"
        r.font.bold = True
        r.font.size = Pt(36 if n <= 28 else 32 if n <= 40 else 28 if n <= 56 else 24)
    else:
        r.font.size = Pt(44 if n <= 24 else 38 if n <= 34 else 32 if n <= 48 else 28)
    # No colour here: titles inherit each template's own title style.


def _content_slide(prs, deck, sd, number, logo, tpl):
    group = tpl["group"]
    geo = GEOMETRY[group]
    kind = sd.get("kind") or "content"
    lay = _layout(prs, "Two Content" if kind == "columns" else "Title and Content")
    s = prs.slides.add_slide(lay)
    title = str(sd.get("title") or "").strip()[:140]
    _set_title(s, title, group)
    if logo and deck.get("logo_on_all_slides"):
        s.shapes.title.width = s.shapes.title.width - Inches(1.0)
        _fit_picture(s, logo, Inches(12.2), Inches(0.3), Inches(0.9), Inches(0.9))
    bodies = sorted((ph for ph in s.placeholders if ph.placeholder_format.idx in (1, 2)), key=lambda ph: ph.placeholder_format.idx)
    numbered = sd.get("list_style") == "numbers"

    if kind == "columns":
        for ph, key, head_key in zip(bodies, ("left", "right"), ("left_heading", "right_heading")):
            bullets = _clean_bullets(sd.get(key))
            heading = str(sd.get(head_key) or "").strip()[:80]
            if not bullets and not heading:
                _remove(ph)
                continue
            box = (ph.left / 914400, ph.top / 914400, ph.width / 914400, ph.height / 914400)
            _write_bullets(ph, bullets or [{"text": " ", "level": 0}], box, numbered)
            if heading:
                first = ph.text_frame.paragraphs[0]
                hp = copy.deepcopy(first._p)
                first._p.addprevious(hp)
                from pptx.text.text import _Paragraph
                hpara = _Paragraph(hp, first._parent)
                for run in list(hpara.runs)[1:]:
                    run._r.getparent().remove(run._r)
                hpara.runs[0].text = heading
                hpara.runs[0].font.bold = True
                hppr = hp.get_or_add_pPr()
                etree.SubElement(hppr, qn("a:buNone"))
    else:
        body = bodies[0] if bodies else None
        bullets = _clean_bullets(sd.get("bullets"))
        media = sd.get("media") if isinstance(sd.get("media"), dict) else None
        pos = sd.get("media_position") if sd.get("media_position") in ("right", "below", "full") else "right"
        if media and not bullets:
            pos = "full"
        L, T, W, H = geo["body"]
        if media and pos == "right":
            body_box, media_box = (L, T, geo["right_text_w"], H), geo["right_media"]
        elif media and pos == "below":
            body_box, media_box = (L, T, W, geo["below_text_h"]), geo["below_media"]
        elif media:
            body_box, media_box = None, geo["full_media"]
        else:
            body_box, media_box = (L, T, W, H), None
        if body is not None:
            if bullets and body_box:
                body.left, body.top, body.width, body.height = (Inches(v) for v in body_box)
                _write_bullets(body, bullets, body_box, numbered)
            else:
                _remove(body)
        if media and media_box:
            _add_media(s, media, tuple(Inches(v) for v in media_box))

    if deck.get("slide_numbers", True):
        _add_slide_number(s, lay, number, group)
    if group == "tutor":
        _add_footer(s, lay, _tutor_footer(deck))
    notes = str(sd.get("notes") or "").strip()
    if notes:
        s.notes_slide.notes_text_frame.text = notes[:4000]
    return s


def _tutor_footer(deck):
    ts = deck.get("title_slide") or {}
    if deck.get("footer") is not None:
        return str(deck.get("footer"))
    code, course = str(ts.get("code") or "").strip(), str(ts.get("course") or "").strip()
    return "  ·  ".join(x for x in (code, course) if x)


def _closing_slide(prs, deck, sd, number, tpl):
    group = tpl["group"]
    big = str(sd.get("big") or "Thank you").strip()[:60]
    if group == "student":
        lay = _layout(prs, "Title and Content")
        s = prs.slides.add_slide(lay)
        _set_title(s, str(sd.get("title") or "").strip()[:140], group)
        for ph in list(s.placeholders):
            if ph.placeholder_format.idx == 1:
                _remove(ph)
        box = s.shapes.add_textbox(Inches(0.9), Inches(2.4), Inches(11.5), Inches(3.0))
        box.text_frame.word_wrap = True
        box.text_frame.vertical_anchor = MSO_ANCHOR.MIDDLE
        p = box.text_frame.paragraphs[0]
        p.alignment = PP_ALIGN.CENTER
        r = p.add_run()
        r.text = big.upper()
        r.font.name = "Arial Black"
        r.font.bold = True
        r.font.size = Pt(72 if len(big) <= 14 else 54)
        r.font.color.theme_color = MSO_THEME_COLOR.ACCENT_1
        r.font.color.brightness = -0.25
        if deck.get("slide_numbers", True):
            _add_slide_number(s, lay, number, group)
        return s
    # Tutor: the lecture deck's closing layout — a panel above its dark caption
    # strip — with the words set in the panel instead of the original's photo.
    lay = _layout(prs, "Picture with Caption")
    s = prs.slides.add_slide(lay)
    for ph in list(s.placeholders):
        if ph.placeholder_format.type not in (PP_PLACEHOLDER.TITLE, PP_PLACEHOLDER.CENTER_TITLE):
            _remove(ph)
    panel = s.shapes.add_shape(MSO_SHAPE.RECTANGLE, 0, 0, SLIDE_W, Inches(5.01))
    panel.fill.solid()
    panel.fill.fore_color.rgb = RGBColor.from_string(tpl.get("panel") or "3A4245")
    panel.line.fill.background()
    panel.shadow.inherit = False
    _to_back(panel)
    accent = s.shapes.add_shape(MSO_SHAPE.RECTANGLE, Inches(5.67), Inches(3.72), Inches(2.0), Inches(0.08))
    accent.fill.solid()
    accent.fill.fore_color.rgb = RGBColor.from_string(tpl.get("frame") or "FF6D17")
    accent.line.fill.background()
    accent.shadow.inherit = False
    box = s.shapes.add_textbox(Inches(0.9), Inches(1.0), Inches(11.5), Inches(2.6))
    box.text_frame.word_wrap = True
    box.text_frame.vertical_anchor = MSO_ANCHOR.MIDDLE
    p = box.text_frame.paragraphs[0]
    p.alignment = PP_ALIGN.CENTER
    r = p.add_run()
    r.text = big
    r.font.name = "Bookman Old Style"
    r.font.size = Pt(80 if len(big) <= 14 else 60)
    r.font.color.rgb = WHITE
    t = s.shapes.title
    t.text_frame.text = str(sd.get("title") or "Any questions").strip()[:80].upper()
    return s


# ------------------------------------------------ section, quote, picture
def _section_slide(prs, deck, sd, number, tpl):
    """A divider between parts of a talk, on each template's own Section
    Header layout: the student's title sits in its blue band (made larger
    than the layout's timid default); the tutor's is a big serif title over
    a rule with a small-capitals subtitle."""
    group = tpl["group"]
    lay = _layout(prs, "Section Header")
    s = prs.slides.add_slide(lay)
    title = str(sd.get("title") or "").strip()[:120] or " "
    sub_text = str(sd.get("sub") or "").strip()[:200]
    for ph in list(s.placeholders):
        t = ph.placeholder_format.type
        if t in (PP_PLACEHOLDER.TITLE, PP_PLACEHOLDER.CENTER_TITLE):
            tf = ph.text_frame
            tf.text = ""
            r = tf.paragraphs[0].add_run()
            r.text = title
            if group == "student":
                r.font.size = Pt(32 if len(title) <= 34 else 26)
                r.font.bold = True
            else:
                r.font.size = Pt(54 if len(title) <= 24 else 44 if len(title) <= 40 else 36)
        elif t == PP_PLACEHOLDER.BODY:
            if sub_text:
                ph.text_frame.text = sub_text
                for p in ph.text_frame.paragraphs:
                    for r in p.runs:
                        r.font.size = Pt(20)
            else:
                _remove(ph)
        elif t not in (PP_PLACEHOLDER.SLIDE_NUMBER,):
            _remove(ph)
    if deck.get("slide_numbers", True):
        _add_slide_number(s, lay, number, group)
    if group == "tutor":
        _add_footer(s, lay, _tutor_footer(deck))
    return s


def _quote_slide(prs, deck, sd, number, tpl):
    """A quotation on the template's plain layout: a large opening quote mark
    in the template's accent, the quote centred, the attribution beneath."""
    group = tpl["group"]
    # Student: "Title Only" keeps the signature band and its numbered chip
    # (the plain layout hides them); tutor: the plain layout keeps its band.
    lay = _layout(prs, "Title Only" if group == "student" else "Blank")
    s = prs.slides.add_slide(lay)
    for ph in list(s.placeholders):
        _remove(ph)
    quote = str(sd.get("quote") or "").strip().strip('"“”')[:400] or " "
    by = str(sd.get("by") or "").strip()[:120]
    top = Inches(2.05) if group == "student" else Inches(0.9)
    height = Inches(4.2) if group == "student" else Inches(5.2)
    mark = s.shapes.add_textbox(Inches(0.9), top - Inches(0.35), Inches(1.6), Inches(1.6))
    mr = mark.text_frame.paragraphs[0].add_run()
    mr.text = "“"
    mr.font.size = Pt(120)
    mr.font.bold = True
    if group == "student":
        mr.font.color.theme_color = MSO_THEME_COLOR.ACCENT_2
    else:
        mr.font.color.rgb = RGBColor.from_string(tpl.get("frame") or "FF6D17")
        mr.font.name = "Bookman Old Style"
    box = s.shapes.add_textbox(Inches(1.6), top, Inches(10.1), height)
    tf = box.text_frame
    tf.word_wrap = True
    tf.vertical_anchor = MSO_ANCHOR.MIDDLE
    n = len(quote)
    p = tf.paragraphs[0]
    p.alignment = PP_ALIGN.CENTER
    r = p.add_run()
    r.text = quote
    r.font.size = Pt(40 if n <= 70 else 32 if n <= 140 else 26 if n <= 240 else 22)
    r.font.italic = True
    if group == "tutor":
        r.font.name = "Bookman Old Style"
    r.font.color.theme_color = MSO_THEME_COLOR.TEXT_1
    r.font.color.brightness = 0.15
    if by:
        bp = tf.add_paragraph()
        bp.alignment = PP_ALIGN.CENTER
        bp.space_before = Pt(18)
        br = bp.add_run()
        br.text = "— " + by
        br.font.size = Pt(20)
        br.font.bold = True
        if group == "student":
            br.font.color.theme_color = MSO_THEME_COLOR.ACCENT_1
            br.font.color.brightness = -0.25
        else:
            br.font.color.theme_color = MSO_THEME_COLOR.TEXT_1
            br.font.color.brightness = 0.25
    if deck.get("slide_numbers", True):
        _add_slide_number(s, lay, number, group)
    if group == "tutor":
        _add_footer(s, lay, _tutor_footer(deck))
    _notes(s, sd)
    return s


def _picture_slide(prs, deck, sd, number, tpl):
    """A photo with a caption, on each template's own Picture with Caption
    layout. The photo is fitted whole in the layout's picture area — never
    cropped, so nobody's photo loses a head or a label."""
    group = tpl["group"]
    lay = _layout(prs, "Picture with Caption")
    s = prs.slides.add_slide(lay)
    title = str(sd.get("title") or "").strip()[:120]
    caption = str(sd.get("caption") or "").strip()[:300]
    media = sd.get("media") if isinstance(sd.get("media"), dict) else {}
    data = _image_bytes(media.get("data")) if media.get("type") == "image" else None
    area = None
    for ph in list(s.placeholders):
        t = ph.placeholder_format.type
        if t == PP_PLACEHOLDER.PICTURE:
            area = (ph.left, ph.top, ph.width, ph.height)
            _remove(ph)
        elif t in (PP_PLACEHOLDER.TITLE, PP_PLACEHOLDER.CENTER_TITLE):
            if title:
                ph.text_frame.text = title
            else:
                _remove(ph)
        elif t == PP_PLACEHOLDER.BODY:
            if caption:
                ph.text_frame.text = caption
            else:
                _remove(ph)
        elif t not in (PP_PLACEHOLDER.SLIDE_NUMBER,):
            _remove(ph)
    if area is None:
        area = (Inches(0.9), Inches(0.4), Inches(11.5), Inches(4.6))
    if group == "tutor":
        backdrop = s.shapes.add_shape(MSO_SHAPE.RECTANGLE, area[0], area[1], area[2], area[3])
        backdrop.fill.solid()
        backdrop.fill.fore_color.rgb = RGBColor.from_string(tpl.get("panel") or "3A4245")
        backdrop.line.fill.background()
        backdrop.shadow.inherit = False
        _to_back(backdrop)
    if data:
        pad = Inches(0.15)
        _fit_picture(s, data, area[0] + pad, area[1] + pad, area[2] - 2 * pad, area[3] - 2 * pad)
    _notes(s, sd)
    return s


def _notes(s, sd):
    notes = str(sd.get("notes") or "").strip()
    if notes:
        s.notes_slide.notes_text_frame.text = notes[:4000]



def build_template_deck(deck, out_dir, filename="Presentation.pptx"):
    """deck: {
        template: one of TEMPLATES (or "student"/"tutor"),
        logo: data URL (optional), logo_on_all_slides: bool, slide_numbers: bool,
        title_slide:
            student: {lines: [institution, department, programme], main, sub, tag}
            tutor:   {course, code, subtitle, lecturer, date, picture (data URL)},
        footer: tutor slides' footer text (defaults to "CODE · Course"),
        slides: [{kind: "content" | "columns" | "section" | "quote" | "picture" | "end", title,
                  bullets: [{text, level}], list_style: "bullets" | "numbers",
                  media: {type: "image", data} | {type: "table", rows}
                         | {type: "chart", chart_type, categories, series, title},
                  media_position: "right" | "below" | "full",
                  left/right (bullets) and left_heading/right_heading (columns),
                  big (end), sub (section), quote/by (quote), caption + media image (picture), notes}]
    }  →  path of the saved .pptx"""
    if not isinstance(deck, dict) or not isinstance(deck.get("slides") or [], list):
        raise StudioError("The slides couldn't be read — please try again.")
    slides = [sd for sd in (deck.get("slides") or []) if isinstance(sd, dict)]
    if len(slides) > MAX_SLIDES:
        raise StudioError(f"A deck can have up to {MAX_SLIDES} slides.")
    prs, key, tpl = _open_template(deck.get("template") or "student")
    logo = _image_bytes(deck.get("logo"))
    if deck.get("include_title_slide", True):
        if tpl["group"] == "student":
            _student_title_slide(prs, deck)
        else:
            _tutor_title_slide(prs, deck, tpl)
    for sd in slides:
        number = len(prs.slides) + 1
        kind = sd.get("kind") or "content"
        if kind == "end":
            _closing_slide(prs, deck, sd, number, tpl)
        elif kind == "section":
            _section_slide(prs, deck, sd, number, tpl)
        elif kind == "quote":
            _quote_slide(prs, deck, sd, number, tpl)
        elif kind == "picture":
            _picture_slide(prs, deck, sd, number, tpl)
        else:
            _content_slide(prs, deck, sd, number, logo, tpl)
    if not len(prs.slides):
        raise StudioError("Add at least one slide first.")
    safe = re.sub(r"[^A-Za-z0-9 _.()-]+", "", filename).strip() or "Presentation.pptx"
    if not safe.lower().endswith(".pptx"):
        safe += ".pptx"
    os.makedirs(out_dir, exist_ok=True)
    out_path = os.path.join(out_dir, safe)
    prs.save(out_path)
    return out_path


# ---------------------------------------------------------------- reading
def _flat_shapes(shapes):
    for sh in shapes:
        if sh.shape_type is not None and int(sh.shape_type) == 6:   # a group: read what's inside it
            yield from _flat_shapes(sh.shapes)
        else:
            yield sh


def _picture_data_url(image_blob):
    """A slide picture, shrunk for the editor: at most 1600px on its long
    side, re-saved as JPEG (PNG when it has transparency, e.g. a logo) —
    lecture decks often hold multi-megabyte photos that would otherwise make
    opening the editor a long wait on mobile data."""
    from PIL import Image
    try:
        with Image.open(io.BytesIO(image_blob)) as im:
            im.load()
            has_alpha = im.mode in ("RGBA", "LA") or (im.mode == "P" and "transparency" in im.info)
            im = im.convert("RGBA" if has_alpha else "RGB")
            im.thumbnail((1600, 1600))
            buf = io.BytesIO()
            if has_alpha:
                im.save(buf, "PNG", optimize=True)
                mime = "image/png"
            else:
                im.save(buf, "JPEG", quality=84, optimize=True)
                mime = "image/jpeg"
    except Exception:
        return None
    return f"data:{mime};base64," + base64.b64encode(buf.getvalue()).decode()


def _paragraph_bullets(text_frame):
    out = []
    for p in text_frame.paragraphs:
        text = "".join(r.text for r in p.runs).strip() or p.text.strip() if hasattr(p, "text") else ""
        text = re.sub(r"\s+", " ", text.replace("\v", " ")).strip()
        if text:
            out.append({"text": text[:600], "level": max(0, min(int(p.level or 0), 3))})
    return out


def parse_pptx_to_deck(path, max_pictures=30):
    """Reads an existing presentation into the deck model, so it can be
    reopened in the editor and rebuilt in any template: the title slide's
    text, then per slide its title, bullets with their levels (two text
    columns become a two-column slide), its first picture, table or chart,
    and its speaker notes. A last slide saying thank you / questions becomes
    the closing slide."""
    try:
        prs = Presentation(path)
    except Exception:
        raise StudioError("That PowerPoint file couldn't be opened — it may be damaged or password-protected.")
    slides, title_slide, pictures = [], {}, 0
    all_slides = list(prs.slides)
    for i, s in enumerate(all_slides):
        shapes = list(_flat_shapes(s.shapes))
        title_shape = s.shapes.title
        title = re.sub(r"\s+", " ", title_shape.text_frame.text.replace("\v", " ")).strip() if title_shape is not None and title_shape.has_text_frame else ""
        kinds = {ph.placeholder_format.type for ph in s.placeholders}
        is_title_slide = i == 0 and (PP_PLACEHOLDER.CENTER_TITLE in kinds or PP_PLACEHOLDER.SUBTITLE in kinds or "title slide" in (s.slide_layout.name or "").lower())
        # Slide numbers, dates and footers are the template's furniture, not
        # content — reading them made "3" an extra bullet on slide 3.
        furniture = (PP_PLACEHOLDER.SLIDE_NUMBER, PP_PLACEHOLDER.DATE, PP_PLACEHOLDER.FOOTER)
        texts = [sh for sh in shapes if getattr(sh, "has_text_frame", False) and sh.text_frame.text.strip()
                 and (title_shape is None or sh.shape_id != title_shape.shape_id)
                 and not (sh.is_placeholder and sh.placeholder_format.type in furniture)]
        if is_title_slide:
            raw_lines = [l.strip() for l in (title_shape.text_frame.text if title_shape is not None else "").replace("\v", "\n").split("\n") if l.strip()]
            others = [re.sub(r"\s+", " ", sh.text_frame.text.replace("\v", " ")).strip() for sh in texts]
            code = next((m.group(1) for l in raw_lines for m in [re.match(r"^\((.+)\)$", l)] if m), "")
            course_lines = [l for l in raw_lines if not re.match(r"^\(.+\)$", l)]
            title_slide = {"lines": raw_lines[:4], "main": others[0][:200] if others else "", "sub": others[1][:200] if len(others) > 1 else "",
                           "course": " ".join(course_lines)[:80], "code": code[:30], "subtitle": others[0][:120] if others else ""}
            # The title slide's own pictures are the author's content: a small
            # square one is their logo, a large one the picture beside the
            # title. Mostly-transparent images are skipped — the lecture
            # deck's orange frame is itself a see-through picture laid over
            # its photo, and must not be mistaken for the photo.
            # Topmost first: where pictures overlap, the one on top is what the
            # audience sees (the lecture deck hides a staircase graphic under
            # its title photo).
            for sh in reversed(shapes):
                if sh.shape_type is None or int(sh.shape_type) != 13 or _mostly_transparent(sh.image.blob):
                    continue
                w_in, h_in = sh.width / 914400, sh.height / 914400
                blob = sh.image.blob if max(w_in, h_in) <= 2.5 else _trim_card_border(sh.image.blob)
                url = _picture_data_url(blob)
                if not url:
                    continue
                if max(w_in, h_in) <= 2.5 and "logo" not in title_slide:
                    title_slide["logo"] = url
                elif max(w_in, h_in) > 2.5 and "picture" not in title_slide:
                    title_slide["picture"] = url
            continue
        bodies = sorted([ph for ph in s.placeholders if ph.placeholder_format.idx in (1, 2) and ph.has_text_frame and ph.text_frame.text.strip()],
                        key=lambda ph: ph.placeholder_format.idx)
        sd = {"kind": "content", "title": title[:140]}
        layout_name = (s.slide_layout.name or "").lower()
        if "section" in layout_name:
            others = [re.sub(r"\s+", " ", sh.text_frame.text).strip() for sh in texts]
            slides.append({"kind": "section", "title": title[:120], "sub": (others[0] if others else "")[:200]})
            continue
        all_text = " ".join(re.sub(r"\s+", " ", sh.text_frame.text).strip() for sh in texts).strip()
        if not title and re.match(r'^["\u201c].{10,380}["\u201d]', all_text):
            m = re.match(r'^["\u201c](.+?)["\u201d]\s*(?:[-\u2013\u2014~]+\s*(.+))?$', all_text)
            if m:
                slides.append({"kind": "quote", "quote": m.group(1).strip()[:400], "by": (m.group(2) or "").strip()[:120]})
                continue
        if len(bodies) == 2:
            sd.update(kind="columns", left=_paragraph_bullets(bodies[0].text_frame), right=_paragraph_bullets(bodies[1].text_frame))
        else:
            bullets = []
            for sh in texts:
                bullets.extend(_paragraph_bullets(sh.text_frame))
            sd["bullets"] = bullets[:40]
        media = None
        for sh in shapes:
            if getattr(sh, "has_table", False) and sh.has_table:
                media = {"type": "table", "rows": [[c.text.strip()[:200] for c in r.cells] for r in sh.table.rows][:20]}
                break
            if getattr(sh, "has_chart", False) and sh.has_chart:
                try:
                    plot = sh.chart.plots[0]
                    media = {"type": "chart", "chart_type": "pie" if "PIE" in str(sh.chart.chart_type) else "bar" if "BAR" in str(sh.chart.chart_type) else "line" if "LINE" in str(sh.chart.chart_type) else "column",
                             "categories": [str(c) for c in plot.categories], "series": [{"name": se.name, "values": list(se.values)} for se in plot.series]}
                except Exception:
                    media = None
                if media:
                    break
            if sh.shape_type is not None and int(sh.shape_type) == 13 and pictures < max_pictures:
                url = _picture_data_url(sh.image.blob)
                if url:
                    media = {"type": "image", "data": url}
                    pictures += 1
                    break
        if media:
            sd["media"] = media
            sd["media_position"] = "right" if (sd.get("bullets") or sd.get("left")) else "full"
        if s.has_notes_slide:
            notes = s.notes_slide.notes_text_frame.text.strip()
            if notes:
                sd["notes"] = notes[:4000]
        joined = (title + " " + " ".join(b["text"] for b in sd.get("bullets", []))).lower()
        if i == len(all_slides) - 1 and re.search(r"\b(thank you|thanks|questions?)\b", joined) and len(joined) < 80:
            sd = {"kind": "end", "title": title[:80] if "question" in title.lower() else "", "big": "Thank you"}
        slides.append(sd)
    logo = title_slide.pop("logo", None)
    return {"title_slide": title_slide, "slides": slides[:MAX_SLIDES], "slide_numbers": True, "logo": logo}


def _trim_card_border(blob):
    """A title photo is often pasted onto a white card with decorative frame
    strokes drawn around it (the lecture deck's anatomy photo has its orange
    brackets drawn into the same image). Placed in a template that draws its
    own frame, that showed a frame within a frame, so the picture is trimmed
    to the photo itself: everything that isn't white card or warm frame
    stroke, with the thin anti-aliased edges of the strokes filtered away.
    Cautious by design: only pictures with real frame strokes around them
    (1.5–25% of the picture) are trimmed, and only when a clear border comes
    away — ordinary photos, scans and charts are left exactly as they are."""
    from PIL import Image, ImageChops, ImageFilter
    try:
        with Image.open(io.BytesIO(blob)) as im:
            rgb = im.convert("RGB")
    except Exception:
        return blob
    r, g, b = rgb.split()
    band = lambda ch, lo, hi: ch.point(lambda v: 255 if lo <= v <= hi else 0)
    white = ImageChops.multiply(ImageChops.multiply(band(r, 233, 255), band(g, 233, 255)), band(b, 233, 255))
    stroke = ImageChops.multiply(ImageChops.multiply(band(r, 190, 255), band(g, 40, 190)), band(b, 0, 120))
    # Only a picture that really has frame strokes around it is touched: a
    # white margin alone (a scanned page, a chart) isn't a frame, and the
    # stroke clean-up below would eat thin chart lines and labels.
    stroke_share = stroke.histogram()[255] / float(rgb.width * rgb.height)
    if not 0.015 <= stroke_share <= 0.25:
        return blob
    content = ImageChops.invert(ImageChops.lighter(white, stroke)).filter(ImageFilter.MinFilter(5))
    box = content.getbbox()
    if not box:
        return blob
    area = (box[2] - box[0]) * (box[3] - box[1]) / float(rgb.width * rgb.height)
    if area > 0.9 or area < 0.12:
        return blob
    pad = 3
    box = (max(0, box[0] - pad), max(0, box[1] - pad), min(rgb.width, box[2] + pad), min(rgb.height, box[3] + pad))
    out = io.BytesIO()
    rgb.crop(box).save(out, "PNG")
    return out.getvalue()


def _mostly_transparent(blob):
    from PIL import Image
    try:
        with Image.open(io.BytesIO(blob)) as im:
            if im.mode not in ("RGBA", "LA", "P"):
                return False
            alpha = im.convert("RGBA").getchannel("A").resize((64, 64))
            return sum(1 for a in alpha.getdata() if a < 40) > 0.5 * 64 * 64
    except Exception:
        return False
